// What the site knows, and the shape of the files it reads.
//
// `catalog.json`, `content/<project>/<version>.json` and `search.json` are generated by `scripts/` and are the only inputs
// this app has: no API, no database, and no knowledge of the tool that produced them.

export interface Section {
	id: string;
	title: string;
	description: string;
}

export interface PageEntry {
	/** The address of the page inside its version: `index`, `ports`, or `index.html` for an imported page. */
	href: string;
	title: string;
	/** Authored here as Markdown, or written by a project's own build. */
	kind: 'md' | 'build';
	description?: string;
}

export interface Version {
	version: string;
	/** When the newest page of this version was written or imported, ISO. */
	builtAt?: string;
	pages: PageEntry[];
}

export interface Project {
	id: string;
	title: string;
	section: string;
	summary: string;
	/** The newest version, by number. */
	latest: string;
	versions: Version[];
}

export interface Catalog {
	generated: string;
	sections: Section[];
	projects: Project[];
}

export interface Heading {
	id: string;
	text: string;
	level: number;
}

export interface CompiledPage {
	title: string;
	description?: string;
	html: string;
	headings: Heading[];
}

export interface BodyFile {
	pages: Record<string, CompiledPage>;
}

export interface SearchRecord {
	t: string;
	p: string;
	pn: string;
	v: string;
	s: string;
	u: string;
	h: string[];
	x: string;
}

export interface SearchIndex {
	generated: string;
	pages: SearchRecord[];
}
